    @Autowired
    GraphQlTester graphQlTester;

    @MockitoBean OrderRepository orders;
    @MockitoBean OrderLineRepository lines;
    @MockitoBean CustomerRepository customers;
    @MockitoBean ItemRepository items;
    @MockitoBean OrderService service;

    @Test
    void returnsTheFieldsAskedFor() {
        given(orders.findById(1L)).willReturn(
                Optional.of(new Order(1L, 3_000, Instant.parse("2026-09-01T10:00:00Z"))));

        graphQlTester.document("{ order(id: 1) { status total } }")
                .execute()
                .path("order.status").entity(String.class).isEqualTo("PLACED")
                .path("order.total").entity(Integer.class).isEqualTo(3000);
    }

    @Test
    void aMissingOrderIsNotFound() {
        given(orders.findById(999L)).willReturn(Optional.empty());

        graphQlTester.document("{ order(id: 999) { id } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND);
    }

    // Three orders from two customers: one count query, not one per customer.
    @Test
    void orderCountsForEveryCustomerComeFromOneQuery() {
        Customer ada = new Customer(1L, "Ada", "ada@example.com", "GOLD");
        Customer grace = new Customer(2L, "Grace", "grace@example.com", "SILVER");
        given(orders.findBy(any(), any(), any())).willReturn(
                window(order(1L, 1L), order(2L, 2L), order(3L, 1L)));
        given(customers.findAllById(any())).willReturn(List.of(ada, grace));
        given(orders.countByCustomerIdIn(any())).willReturn(
                List.of(new CustomerOrderCount(1L, 2), new CustomerOrderCount(2L, 1)));

        graphQlTester.document("{ orders { edges { node { customer { name orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class).isEqualTo(2)
                .path("orders.edges[1].node.customer.orderCount").entity(Integer.class).isEqualTo(1)
                .path("orders.edges[2].node.customer.orderCount").entity(Integer.class).isEqualTo(2);

        verify(orders, times(1)).countByCustomerIdIn(List.of(1L, 2L));
    }

    // A customer the count query has no row for has placed nothing.
    @Test
    void aCustomerWithoutOrdersCountsZero() {
        Customer ada = new Customer(1L, "Ada", "ada@example.com", "GOLD");
        given(orders.findBy(any(), any(), any())).willReturn(window(order(1L, 1L)));
        given(customers.findAllById(any())).willReturn(List.of(ada));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of());

        graphQlTester.document("{ orders { edges { node { customer { orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class).isEqualTo(0);
    }

    @Test
    void customerOrdersReturnsTenByDefaultOrderedById() {
        given(customers.existsById(1L)).willReturn(true);
        given(orders.findByCustomerId(eq(1L), any(), any(), any())).willReturn(
                window(order(7L, 1L), order(9L, 1L)));

        graphQlTester.document("{ customerOrders(customerId: 1) { edges { node { id } } } }")
                .execute()
                .path("customerOrders.edges[0].node.id").entity(String.class).isEqualTo("7")
                .path("customerOrders.edges[1].node.id").entity(String.class).isEqualTo("9");

        ArgumentCaptor<Limit> limit = ArgumentCaptor.forClass(Limit.class);
        ArgumentCaptor<Sort> sort = ArgumentCaptor.forClass(Sort.class);
        verify(orders).findByCustomerId(eq(1L), any(ScrollPosition.class), limit.capture(), sort.capture());
        assertThat(limit.getValue().max()).isEqualTo(10);
        assertThat(sort.getValue()).isEqualTo(Sort.by("id"));
    }

    // The cursor from one page is the position the next page starts after.
    @Test
    void customerOrdersPaginatesWithFirstAndAfter() {
        given(customers.existsById(1L)).willReturn(true);
        given(orders.findByCustomerId(eq(1L), any(), any(), any())).willReturn(
                window(order(7L, 1L), order(9L, 1L)));

        String cursor = graphQlTester
                .document("{ customerOrders(customerId: 1, first: 2) { pageInfo { endCursor } } }")
                .execute()
                .path("customerOrders.pageInfo.endCursor").entity(String.class).get();

        graphQlTester.document("query($after: String) "
                        + "{ customerOrders(customerId: 1, first: 1, after: $after) { edges { node { id } } } }")
                .variable("after", cursor)
                .execute()
                .path("customerOrders.edges[0].node.id").entity(String.class).isEqualTo("7");

        ArgumentCaptor<ScrollPosition> position = ArgumentCaptor.forClass(ScrollPosition.class);
        ArgumentCaptor<Limit> limit = ArgumentCaptor.forClass(Limit.class);
        verify(orders, times(2))
                .findByCustomerId(eq(1L), position.capture(), limit.capture(), any(Sort.class));
        assertThat(limit.getAllValues()).extracting(Limit::max).containsExactly(2, 1);
        assertThat(position.getAllValues().get(0)).isEqualTo(ScrollPosition.keyset());
        assertThat(position.getAllValues().get(1)).isInstanceOf(KeysetScrollPosition.class);
        assertThat(((KeysetScrollPosition) position.getAllValues().get(1)).getKeys())
                .containsEntry("id", 9);
    }

    @Test
    void customerOrdersForAMissingCustomerIsNotFound() {
        given(customers.existsById(42L)).willReturn(false);

        graphQlTester.document("{ customerOrders(customerId: 42) { edges { node { id } } } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND
                        && error.getMessage().contains("42"));
    }

    private static Window<Order> window(Order... items) {
        List<Order> list = List.of(items);
        return Window.from(list, index -> ScrollPosition.forward(
                Map.of("id", list.get(index).getId())));
    }

    // The id is database generated, so tests that care about it set it directly.
    private static Order order(Long id, Long customerId) {
        Order order = new Order(customerId, 3_000, Instant.parse("2026-09-01T10:00:00Z"));
        ReflectionTestUtils.setField(order, "id", id);
        return order;
    }
}
