    @Test
    void returnsTheFieldsAskedFor() {
        given(orders.findById(1L)).willReturn(
                Optional.of(new Order(1L, 3_000, Instant.parse("2026-09-01T10:00:00Z"))));

        graphQlTester.document("{ order(id: 1) { status total } }")
                .execute()
                .path("order.status").entity(String.class).isEqualTo("PLACED")
                .path("order.total").entity(Integer.class).isEqualTo(3000);
    }

    @Test
    void aMissingOrderIsNotFound() {
        given(orders.findById(999L)).willReturn(Optional.empty());

        graphQlTester.document("{ order(id: 999) { id } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND);
    }

    // Three orders from two customers: one count query, not one per customer.
    @Test
    void orderCountsForEveryCustomerComeFromOneQuery() {
        Customer ada = new Customer(1L, "Ada", "ada@example.com", "GOLD");
        Customer grace = new Customer(2L, "Grace", "grace@example.com", "SILVER");
        given(orders.findBy(any(), any(), any())).willReturn(
                window(order(1L, 1L), order(2L, 2L), order(3L, 1L)));
        given(customers.findAllById(any())).willReturn(List.of(ada, grace));
        given(orders.countByCustomerIdIn(any())).willReturn(
                List.of(new CustomerOrderCount(1L, 2), new CustomerOrderCount(2L, 1)));

        graphQlTester.document("{ orders { edges { node { customer { name orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class).isEqualTo(2)
                .path("orders.edges[1].node.customer.orderCount").entity(Integer.class).isEqualTo(1)
                .path("orders.edges[2].node.customer.orderCount").entity(Integer.class).isEqualTo(2);

        verify(orders, times(1)).countByCustomerIdIn(List.of(1L, 2L));
    }

