        given(customers.findAllById(any())).willReturn(List.of(ada));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of());

        graphQlTester.document("{ orders { edges { node { customer { orderCount } } } } }")
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class).isEqualTo(0);
    }

