                        + "{ customerOrders(customerId: 1, first: 1, after: $after) { edges { node { id } } } }")
                .variable("after", cursor)
                .execute()
                .path("customerOrders.edges[0].node.id").entity(String.class).isEqualTo("7");

        ArgumentCaptor<ScrollPosition> position = ArgumentCaptor.forClass(ScrollPosition.class);
        ArgumentCaptor<Limit> limit = ArgumentCaptor.forClass(Limit.class);
        verify(orders, times(2))
                .findByCustomerId(eq(1L), position.capture(), limit.capture(), any(Sort.class));
        assertThat(limit.getAllValues()).extracting(Limit::max).containsExactly(2, 1);
        assertThat(position.getAllValues().get(0)).isEqualTo(ScrollPosition.keyset());
        assertThat(position.getAllValues().get(1)).isInstanceOf(KeysetScrollPosition.class);
        assertThat(((KeysetScrollPosition) position.getAllValues().get(1)).getKeys())
                .containsEntry("id", 9);
    }

