                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND
                        && error.getMessage().contains("42"));
    }

    private static Window<Order> window(Order... items) {
        List<Order> list = List.of(items);
        return Window.from(list, index -> ScrollPosition.forward(
                Map.of("id", list.get(index).getId())));
    }

